typedef struct Node {
    int data;
    struct Node *next;
} Node;
void insertBefore(Node *head, Node *p, Node *s) {
    Node *prev = head;
    while (prev->next != p)
        prev = __1__;
    s->next = __2__;
    __3__ = s;
}
void printList(const Node *head) {
    const Node *p = head->next;
    while (p != NULL) {
        printf("%d", p->data);
        if (p->next != NULL) printf("->");
        p = p->next;
    }
    putchar('\n');
